const el=id=>document.getElementById(id), key='percussion-challenges-v2';
const levels={beginner:'Start with the original 30 challenges: keep a pulse, follow a repeated part, and learn instrument and recording clues.',intermediate:'Listen for a clear main style. After choosing, name one audible clue; speed or the song title alone is not enough.',advanced:'Listen across the whole arrangement. Decide whether styles alternate between sections or combine in simultaneous layers.'};
let level='beginner',active=songs[0].id,persistent=true,state={rounds:{}};
try {const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&saved.rounds&&typeof saved.rounds==='object')for(const s of songs){const r=saved.rounds[s.id];if(r&&typeof r.firstCorrect==='boolean'&&typeof r.done==='boolean')state.rounds[s.id]={firstCorrect:r.firstCorrect,done:r.done};}} catch {persistent=false;}
const collection=()=>songs.filter(s=>s.level===level);
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{persistent=false;}stats();}
function stats(){const group=collection(),rounds=group.map(s=>state.rounds[s.id]).filter(Boolean),done=rounds.filter(r=>r.done).length;el('song-progress').textContent=done+' / '+group.length+' completed in '+level+(done===group.length?' — level complete!':'');el('score').textContent=rounds.filter(r=>r.firstCorrect).length+' / '+rounds.length+' correct on first try';el('progress-fill').style.width=done/group.length*100+'%';el('save-status').textContent=persistent?'Progress saved in this browser.':'Progress lasts for this visit; browser storage is unavailable.';}
function filtered(){return collection().filter(s=>(el('song-status').value==='all'||Boolean(state.rounds[s.id]?.done)===(el('song-status').value==='done')));}
function renderList(){const found=filtered();el('song-list').replaceChildren();el('result-count').textContent=found.length+' recordings in this view';for(const s of found){const li=document.createElement('li'),b=document.createElement('button');b.setAttribute('aria-current',String(active===s.id));b.textContent=(state.rounds[s.id]?.done?'✓ ':'')+s.title;const small=document.createElement('small');small.textContent=s.artist;b.append(small);b.onclick=()=>show(s.id);li.append(b);el('song-list').append(li);}if(!found.length){const li=document.createElement('li');li.textContent='No songs in this view. Try another completion filter.';el('song-list').append(li);}el('next-song').disabled=!found.length;}
function player(s,load=false){const stage=el('song-player');stage.replaceChildren();if(load){const frame=document.createElement('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+s.video+'?playsinline=1';frame.title=s.title+' — '+s.artist;frame.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';stage.append(frame);return;}const img=document.createElement('img');img.className='cover';img.src='https://i.ytimg.com/vi/'+s.video+'/hqdefault.jpg';img.alt='';const b=document.createElement('button');b.className='play-cover';b.textContent='▶ Play recording here';b.onclick=()=>player(s,true);stage.append(img,b);}
function question(s,reset=false){el('question-kind').textContent=s.kind;el('question').textContent=s.question;el('answers').replaceChildren();el('feedback').textContent='';const done=state.rounds[s.id]?.done&&!reset;for(const [i,option] of s.options.entries()){const b=document.createElement('button');b.textContent=String.fromCharCode(65+i)+'. '+option;b.disabled=Boolean(done);if(done&&option===s.answer)b.className='correct';b.onclick=()=>{const correct=option===s.answer;if(!state.rounds[s.id])state.rounds[s.id]={firstCorrect:correct,done:false};if(correct)state.rounds[s.id].done=true;b.className=correct?'correct':'wrong';b.disabled=true;el('feedback').textContent=correct?'Correct! '+s.explanation:'Not quite. Listen again, compare the remaining choices, and try once more.';if(correct){el('retry').hidden=false;for(const button of el('answers').children)button.disabled=true;}save();renderList();};el('answers').append(b);}if(done)el('feedback').textContent='Completed. '+s.explanation;el('retry').hidden=!done;}
function show(id){const s=songs.find(s=>s.id===id);if(!s)return;active=id;const group=collection();el('song-number').textContent=level+' · Song '+String(group.indexOf(s)+1).padStart(2,'0')+' / '+group.length;el('song-title').textContent=s.title;el('song-artist').textContent=s.artist+' · '+s.album;el('song-credit').textContent=s.credit;el('practice-purpose').textContent=s.purpose;el('listening-cue').textContent='Listen for: '+s.task;el('album-source').href=s.source;el('source-details').open=false;player(s);question(s);stats();renderList();}
function selectLevel(value){if(!levels[value])return;level=value;el('song-status').value='all';for(const b of document.querySelectorAll('[data-level]'))b.setAttribute('aria-pressed',String(b.dataset.level===level));el('level-purpose').textContent=levels[level];show(collection()[0].id);}
for(const b of document.querySelectorAll('[data-level]'))b.onclick=()=>selectLevel(b.dataset.level);
el('retry').onclick=()=>{question(songs.find(s=>s.id===active),true);el('feedback').textContent='Practice replay — your first-try score stays unchanged.';};
el('reload-player').onclick=()=>player(songs.find(s=>s.id===active),true);
el('next-song').onclick=()=>{const list=filtered();if(!list.length)return;const i=list.findIndex(s=>s.id===active);show(list[(i+1)%list.length].id);el('song-title').setAttribute('tabindex','-1');el('song-title').focus();};
el('song-status').addEventListener('change',()=>{const list=filtered();if(list.length&&!list.some(s=>s.id===active))show(list[0].id);else renderList();});selectLevel('beginner');
